  1	\chapter{Games, strategies, and conditionally linear distributions}
  2	\label{chap:qpbt-games}
  3	% Paper label sec:games kept for cross-reference fidelity; resolves to the chapter number.
  4	\label{sec:games}
  5	
  6	This chapter records the vocabulary in which the quantum Pauli basis test and its analysis are phrased: two-player one-round games and tensor product strategies, the consistency and state-dependent distance calculus for families of measurements, and conditionally linear functions and distributions, the class of question distributions used by the tests of Chapter~\ref{chap:qpbt-test}. The presentation follows \cite{Ji2020MIPStar}; the distance calculus is imported there from \cite{Natarajan2018NEEXP} and \cite{Ji2020LowIndividualDegree}.
  7	
  8	\section{Measurements and observables}
  9	
 10	\begin{definition}[POVMs, sub-measurements, and observables]\label{def:povm-conventions}
 11		\uses{def:submeasurement}
 12		% Finiteness of the outcome set is stated explicitly here; the source leaves it implicit,
 13		% and the measurement and submeasurement definitions referenced below assume finite
 14		% outcome sets.
 15		Quantum measurements are modeled as positive operator-valued measures (POVMs). A \emph{POVM} on a finite-dimensional Hilbert space $\mathcal H$ is a family of positive semidefinite operators $\{M_a\}_{a \in S}$ indexed by outcomes $a$ ranging over a finite set $S$ such that $\sum_a M_a = \Id$; if the latter condition is relaxed to $\sum_a M_a \le \Id$, then $\{M_a\}$ is a \emph{sub-measurement}. (POVMs and sub-measurements are thus exactly the measurements and submeasurements of Definition~\ref{def:submeasurement}.) The probability that the measurement returns outcome $a$ on a state $\ket{\psi}$ is
 16		\[
 17			\Prb(a) = \bra{\psi} M_a \ket{\psi}\,.
 18		\]
 19		A POVM $M = \{M_a\}$ is \emph{projective} if each operator $M_a$ is a projector ($M_a^2 = M_a$); this automatically implies that $M_a M_b = M_b M_a = 0$ for distinct outcomes $a \ne b$. An \emph{observable} is a unitary matrix. A \emph{binary observable} is an observable $O$ such that $O^2 = \Id$, i.e.\ $O$ has eigenvalues in $\{-1,1\}$.
 20	
 21		Subscripts of a measurement index the outcome, and superscripts index different measurements. When the outcome of a measurement $\{M^x_{a,\,b}\}$ consists of two parts $a$ and $b$, we write $\{M^x_a\}$ and $\{M^x_b\}$ for its \emph{marginals}
 22		\[
 23			M^x_a = \sum_b M^x_{a,\,b}\,, \qquad M^x_b = \sum_a M^x_{a,\,b}\,;
 24		\]
 25		for every $x$ both marginals are again POVMs.
 26	\end{definition}
 27	
 28	\begin{definition}[Bracket notation for post-processed measurements]\label{def:bracket}
 29		\lean{MIPStarRE.Quantum.Measurement.postprocess}
 30		\leanok
 31		\uses{def:povm-conventions, def:post-processing}
 32		Let $\mathcal A$ and $\mathcal B$ be finite sets, let $\{M^x_a\}_{a \in \mathcal A}$ be a family of POVMs indexed by $x \in \mathcal X$, and let $f \colon \mathcal A \to \mathcal B$ be an arbitrary function. We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from $\{M^x_a\}$ by applying the function $f$ to the outcome before returning it:
 33		\[
 34			M^x_{[f(\cdot)=b]} = \sum_{a\,:\,f(a)=b} M^x_a\,,
 35		\]
 36		and $M^x_{[f(\cdot)=b]} = 0$ when $b$ is not in the image of $f$. When the outcome $a$ has a natural interpretation as a tuple $(a_1,\dots,a_k)$, we also write, for $i \in \{1,\dots,k\}$,
 37		\[
 38			M^x_{[a_i=b]} = \sum_{(a_1,\dots,a_k)\,:\,a_i=b} M^x_{(a_1,\dots,a_k)}\,.
 39		\]
 40		For each fixed $x$ this is the post-processing operation of Definition~\ref{def:post-processing}.
 41	\end{definition}
 42	
 43	\begin{remark}[Naimark dilation for strategies]\label{rem:naimark-for-games}
 44		The symmetrization argument of Lemma~\ref{lem:symmetric-strat} below invokes Naimark dilation in the form of Theorem~\ref{thm:naimark} (stated and proved in Chapter~\ref{chap:projective}): a bipartite state together with two sub-measurement families can be replaced, without changing any of the correlations $\bra{\psi} A^x_a \ot B^y_b \ket{\psi}$, by a product-extended state together with projective sub-measurements on the enlarged spaces. When the input families are complete measurements, the dilated projective sub-measurements can be completed by assigning the residual projector of each family to one fixed outcome; the resulting projective measurements reproduce the same correlations on the extended state, since the correlation-preservation identity forces the extended state to lie in the range of the total projector of each dilated family. This completed form, with genuinely projective measurements, is the one used in Lemma~\ref{lem:symmetric-strat}; for the proof the source refers to Theorem 5.1 of \cite{Ji2020LowIndividualDegree}, which is stated for complete measurements. The source follows its statement of the dilation theorem with a sentence announcing an ``orthogonalization lemma'' from the literature that is never actually stated there; nothing in this chapter depends on it.
 45	\end{remark}
 46	
 47	\section{Games and strategies}
 48	% Paper subsection label sec:strat kept for cross-reference fidelity.
 49	\label{sec:strat}
 50	
 51	\begin{definition}[Two-player one-round games]\label{def:game}
 52		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
 53		\begin{enumerate}
 54			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
 55			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
 56			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
 57			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
 58		\end{enumerate}
 59	\end{definition}
 60	
 61	\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
 62		\uses{def:game, def:povm-conventions}
 63		A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
 64		\begin{itemize}
 65			\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
205			\E_{x \sim \mu} \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi} = O(\delta)\,.
206		\]
207		In this case we say that $\{A^x_a\}$ and $\{B^x_a\}$ are \emph{$\delta$-consistent} on $\ket{\psi}$. As in Definition~\ref{def:state-distance}, the $O(\cdot)$ refers to families of POVMs and states indexed by an implicit parameter $n \in \N$, and is taken as $n \to \infty$.
208	\end{definition}
209	
210	A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.
211	
212	% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:257-274) states this
213	% definition for pairs of POVMs but applies the relation to arbitrary operator families:
214	% to plain operators at 06:313-330, to sets of matrices at 06:364-380, and to products and
215	% commutators, compared against the zero family, at 06:409-445. The general form below,
216	% for arbitrary finite families of operators, is the one of the NEEXP source
217	% (references/neexp-paper/05_quantum_preliminaries.tex:385-391), from which the distance
218	% calculus is imported; the POVM case is singled out after the display.
219	\begin{definition}[State-dependent distance between operator families]\label{def:povm-distance}
220		\uses{def:povm-conventions, def:state-distance}
221		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H$ be a quantum state, and for all $x \in \mathcal X$ let $\{M^x_a\}_{a \in \mathcal A}$ and $\{N^x_a\}_{a \in \mathcal A}$ be two families of linear operators on $\mathcal H$. We say that \emph{$\{M^x_a\}$ and $\{N^x_a\}$ are $\delta$-close on state $\ket{\psi}$ and under distribution $\mu$} if
222		\[
223			\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
224		\]
225		and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance. The principal case is that in which $\{M^x_a\}$ and $\{N^x_a\}$ are POVMs on $\mathcal H$, and we then speak of the state-dependent distance between the POVMs; but the relation is used for arbitrary operator families --- for instance for products of measurement operators, or for commutators compared against the identically zero family, as in Lemma~\ref{lem:commutation-analysis} below.
226	\end{definition}
227	
228	\begin{definition}[Distance between strategies]\label{def:strategy-distance}
229		\lean{MIPStarRE.QPBT.AreCloseStrategies}
230		\leanok
231		\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
232		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
233		\begin{enumerate}
234			\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
235			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
236		\end{enumerate}
237	\end{definition}
238	
239	\begin{remark}[Asymptotic reading of the distance relations]\label{rem:asymptotic-distance}
240		Definitions~\ref{def:state-distance}, \ref{def:consistency}, and \ref{def:povm-distance} are asymptotic: every $\approx_\delta$ and $\simeq_\delta$ statement refers to families of states and measurement families indexed by an implicit parameter $n \in \N$, and the $O(\cdot)$ is taken as $n \to \infty$. None of these relations is a pointwise inequality with an explicit constant. By contrast, the corresponding relations used in the low individual degree chapters (Definitions~\ref{def:simeq} and~\ref{def:approx_delta}) carry no hidden constant. Any explicit quantitative version of the present relations therefore retains the constants absorbed into the $O(\cdot)$; for instance, the triangle inequality of Lemma~\ref{fact:triangle} carries a factor $2$ inside the $O(\cdot)$.
241	\end{remark}
